const defaultState={
  settings:{leadTarget:300,wonTarget:20,month:'2026-08'},
  meta:{seedVersion:SEED_VERSION},
  leads:structuredClone(researchedLeads),
  tours:[],
  activities:[
    {at:'2026-08-31T19:12:00+07:00',type:'lead',text:'เพิ่ม Research ร้านเป้าหมาย 8 ร้านจากชุดพะเยา / พิษณุโลก / แพร่ / น่าน'}
  ]
};

let state=loadState();let currentView='dashboard';let filter={q:'',stage:'all',owner:'all',dup:'all'};
function loadState(){
  try{
    const raw=localStorage.getItem(STORE_KEY);
    const loaded=raw?JSON.parse(raw):structuredClone(defaultState);
    const migrated=migrateState(loaded);
    localStorage.setItem(STORE_KEY,JSON.stringify(migrated));
    return migrated;
  }catch(e){return structuredClone(defaultState)}
}
function migrateState(s){
  s=s&&typeof s==='object'?s:{};
  s.settings={leadTarget:300,wonTarget:20,month:'2026-08',...(s.settings||{})};
  s.meta=s.meta||{};
  s.leads=Array.isArray(s.leads)?s.leads:[];
  s.tours=Array.isArray(s.tours)?s.tours:[];
  s.activities=Array.isArray(s.activities)?s.activities:[];
  s.activities=s.activities.filter(a=>!/Example On Tour Venue|Example New Pub KK|ตัวอย่างวง/.test(a?.text||''));
  // เอาเฉพาะข้อมูล Demo รุ่นแรกออก แต่ไม่แตะ Lead ที่ผู้ใช้กรอกเอง
  s.leads=s.leads.filter(l=>!['Example On Tour Venue','Example New Pub KK'].includes(l?.venue));
  s.tours=s.tours.filter(t=>!['Example On Tour Venue','New Venue Korat'].includes(t?.venue));
  let added=0,enriched=0;
  researchedLeads.forEach(seed=>{
    const i=s.leads.findIndex(l=>norm(l.venue)===norm(seed.venue));
    if(i<0){s.leads.push(structuredClone(seed));added++;return;}
    const current=s.leads[i];
    const enrichFields=['province','area','address','type','source','band','sourceUrl','contact','phone','altPhone','channel','facebook','instagram','tiktok','line','website','capacity','hours','mapUrl'];
    enrichFields.forEach(k=>{if(current[k]===undefined||current[k]===null||current[k]==='')current[k]=seed[k]});
    ['qTraffic','qAudience','qLateHours','qSpace','qPower','qDeal','qReputation'].forEach(k=>{if(typeof current[k]!=='boolean')current[k]=seed[k]});
    if(!current.notes)current.notes=seed.notes;
    if(current.score===undefined||current.score===null||current.score==='')current.score=seed.score;
    current.seedKey=current.seedKey||seed.seedKey;
    enriched++;
  });
  if(s.meta.seedVersion!==SEED_VERSION){
    s.activities.unshift({at:new Date().toISOString(),type:'lead',text:`อัปเดตฐาน Research: เพิ่ม ${added} ร้าน / เติมข้อมูล ${enriched} ร้าน`});
    s.meta.seedVersion=SEED_VERSION;
  }
  return s;
}
function save(){localStorage.setItem(STORE_KEY,JSON.stringify(state));syncHeaderCounts()}
function norm(s=''){return String(s).toLowerCase().replace(/\([^)]*\)/g,' ').replace(/[\s\-_.&/]+/g,' ').replace(/ร้าน|bar|bistro|pub|restaurant|club|cafe|โรงเหล้า/g,'').trim()}
function installedMatch(name){const n=norm(name);if(!n)return null;return installed.find(x=>{const a=norm(x.name);if(a===n)return true;if(Math.min(a.length,n.length)<8)return false;return a.includes(n)||n.includes(a)})||null}
function leadDuplicate(name,id=''){const n=norm(name);return state.leads.find(l=>l.id!==id && norm(l.venue)===n)||null}
function scoreLead(l){if(typeof l.score==='number')return l.score;return ['qTraffic','qAudience','qLateHours','qSpace','qPower','qDeal','qReputation'].reduce((s,k)=>s+(l[k]?{qTraffic:25,qAudience:20,qLateHours:10,qSpace:10,qPower:5,qDeal:15,qReputation:15}[k]:0),0)}
function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function fmtDate(s){if(!s)return'-';const d=new Date(s);if(isNaN(d))return s;return d.toLocaleDateString('th-TH',{day:'2-digit',month:'short'})}
function monthLeads(){const m=state.settings.month;return state.leads.filter(l=>(l.createdAt||'').slice(0,7)===m)}
function syncHeaderCounts(){document.getElementById('navLeadCount').textContent=state.leads.length;document.getElementById('navInstalledCount').textContent=installed.length;const ml=monthLeads();const won=ml.filter(l=>l.stage==='won').length;const lt=+state.settings.leadTarget||300,wt=+state.settings.wonTarget||20;document.getElementById('miniLeads').textContent=ml.length;document.getElementById('miniLeadTarget').textContent=lt;document.getElementById('miniWon').textContent=won;document.getElementById('miniWonTarget').textContent=wt;document.getElementById('miniLeadBar').style.width=Math.min(100,ml.length/lt*100)+'%';document.getElementById('miniWonBar').style.width=Math.min(100,won/wt*100)+'%'}
function toast(t){const el=document.getElementById('toast');el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1800)}
function setPage(title,eyebrow='LOCATION ACQUISITION'){document.getElementById('pageTitle').textContent=title;document.getElementById('pageEyebrow').textContent=eyebrow}

function render(){syncHeaderCounts();document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===currentView));const root=document.getElementById('viewRoot');if(currentView==='dashboard')renderDashboard(root);if(currentView==='leads')renderLeads(root);if(currentView==='pipeline')renderPipeline(root);if(currentView==='tour')renderTour(root);if(currentView==='installed')renderInstalled(root);if(currentView==='team')renderTeam(root);if(currentView==='settings')renderSettings(root)}

